INSERT INTO vecd_conversations(id, payload) VALUES ('CONV-000001', '{"id": "CONV-000001", "dialect": "south", "industry": "real_estate", "kind": "success", "turn_count": 9, "outcome": "won", "missing_stages": [], "qa_score_hint": 81, "linked_root_cause": "RC-000001", "utterances": [{"turn": 1, "speaker": "agent", "text": "Em chào anh/chị, em Minh bên Bất động sản ạ.", "stage": "opening", "emotion": "curious", "intent": "need_more_time"}, {"turn": 2, "speaker": "customer", "text": "Em muốn hiểu rõ đã rồi tính tiếp.", "stage": "rapport", "emotion": "hesitation", "intent": "trust_issue"}, {"turn": 3, "speaker": "agent", "text": "Hiện anh/chị quan tâm nhất điều gì ạ?", "stage": "discovery", "emotion": "frustration", "intent": "decision_maker_missing"}, {"turn": 4, "speaker": "customer", "text": "Người quyết định là em với người nhà.", "stage": "qualification", "emotion": "angry", "intent": "competitor_comparison"}, {"turn": 5, "speaker": "agent", "text": "Điểm khác biệt là chi phí minh bạch.", "stage": "presentation", "emotion": "trust", "intent": "busy"}, {"turn": 6, "speaker": "customer", "text": "Giá sao vậy?", "stage": "pricing", "emotion": "excited", "intent": "interested"}, {"turn": 7, "speaker": "agent", "text": "Em hiểu lo về giá; anh/chị đang so theo tiêu chí nào?", "stage": "objection", "emotion": "neutral", "intent": "ready_to_buy"}, {"turn": 8, "speaker": "customer", "text": "Em cần hợp đồng mẫu trước.", "stage": "closing", "emotion": "exit_intent", "intent": "fake_agreement"}, {"turn": 9, "speaker": "agent", "text": "Em gọi lại theo lịch hẹn, anh/chị tiện nghe không ạ?", "stage": "follow_up", "emotion": "confused", "intent": "soft_rejection"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET payload = EXCLUDED.payload;
