INSERT INTO vecd_conversations(id, payload) VALUES ('CONV-000007', '{"id": "CONV-000007", "dialect": "south", "industry": "cosmetics", "kind": "poor_discovery", "turn_count": 15, "outcome": "lost", "missing_stages": ["discovery"], "qa_score_hint": 47, "linked_root_cause": "RC-000007", "utterances": [{"turn": 1, "speaker": "agent", "text": "Em gọi lại theo đăng ký của anh/chị ạ.", "stage": "opening", "emotion": "neutral", "intent": "ready_to_buy"}, {"turn": 2, "speaker": "customer", "text": "Anh/chị làm bên này lâu chưa vậy?", "stage": "rapport", "emotion": "exit_intent", "intent": "fake_agreement"}, {"turn": 3, "speaker": "agent", "text": "Ai là người cùng quyết định vậy ạ?", "stage": "qualification", "emotion": "confused", "intent": "soft_rejection"}, {"turn": 4, "speaker": "customer", "text": "Cho em xem ví dụ cụ thể nha.", "stage": "presentation", "emotion": "interested", "intent": "price_concern"}, {"turn": 5, "speaker": "agent", "text": "Em tách chi phí và giá trị để dễ so sánh.", "stage": "pricing", "emotion": "curious", "intent": "need_more_time"}, {"turn": 6, "speaker": "customer", "text": "Để hôm khác đi.", "stage": "objection", "emotion": "hesitation", "intent": "trust_issue"}, {"turn": 7, "speaker": "agent", "text": "Anh/chị chọn gói A hay B để em gửi hợp đồng?", "stage": "closing", "emotion": "frustration", "intent": "decision_maker_missing"}, {"turn": 8, "speaker": "customer", "text": "Tuần này em mới quyết được.", "stage": "follow_up", "emotion": "angry", "intent": "competitor_comparison"}, {"turn": 9, "speaker": "agent", "text": "Em xin phép anh/chị 2 phút tư vấn Mỹ phẩm nha.", "stage": "opening", "emotion": "trust", "intent": "busy"}, {"turn": 10, "speaker": "customer", "text": "Anh/chị làm bên này lâu chưa vậy?", "stage": "rapport", "emotion": "excited", "intent": "interested"}, {"turn": 11, "speaker": "agent", "text": "Ngân sách dự kiến khoảng bao nhiêu ạ?", "stage": "qualification", "emotion": "neutral", "intent": "ready_to_buy"}, {"turn": 12, "sp