INSERT INTO vecd_conversations(id, payload) VALUES ('CONV-000028', '{"id": "CONV-000028", "dialect": "north", "industry": "home_appliances", "kind": "difficult_customer", "turn_count": 13, "outcome": "lost", "missing_stages": [], "qa_score_hint": 43, "linked_root_cause": "RC-000028", "utterances": [{"turn": 1, "speaker": "agent", "text": "Em chào anh/chị, em Trang bên Gia dụng.", "stage": "opening", "emotion": "exit_intent", "intent": "fake_agreement"}, {"turn": 2, "speaker": "customer", "text": "Anh/chị tư vấn lâu chưa?", "stage": "rapport", "emotion": "confused", "intent": "soft_rejection"}, {"turn": 3, "speaker": "agent", "text": "Tiêu chí nào quan trọng nhất với anh/chị ạ?", "stage": "discovery", "emotion": "interested", "intent": "price_concern"}, {"turn": 4, "speaker": "customer", "text": "Ngân sách em khoảng 20 triệu.", "stage": "qualification", "emotion": "curious", "intent": "need_more_time"}, {"turn": 5, "speaker": "agent", "text": "Dựa trên nhu cầu giảm rủi ro, bên em đề xuất hướng này ạ.", "stage": "presentation", "emotion": "hesitation", "intent": "trust_issue"}, {"turn": 6, "speaker": "customer", "text": "Có trả góp không?", "stage": "pricing", "emotion": "frustration", "intent": "decision_maker_missing"}, {"turn": 7, "speaker": "agent", "text": "Em gửi giấy tờ/uy tín để anh/chị yên tâm ạ.", "stage": "objection", "emotion": "angry", "intent": "competitor_comparison"}, {"turn": 8, "speaker": "customer", "text": "Chốt hôm nay được ưu đãi gì?", "stage": "closing", "emotion": "trust", "intent": "busy"}, {"turn": 9, "speaker": "agent", "text": "Em gửi lại báo giá và điểm khác biệt chính ạ.", "stage": "follow_up", "emotion": "excited", "intent": "interested"}, {"turn": 10, "speaker": "customer", "text": "Số này bên Gia dụng phải không ạ?", "stage": "opening", "emotion": "neutral", "intent": "ready_to_buy"}, {"turn": 11, "speaker": "agent", "text": "Em hiểu anh/chị đang bận, em nói ngắn gọn ạ.", "stage": "rapport", "emotion": "exit_intent", "intent": "fake_ag