INSERT INTO vecd_conversations(id, payload) VALUES ('CONV-000077', '{"id": "CONV-000077", "dialect": "north", "industry": "repair", "kind": "poor_discovery", "turn_count": 16, "outcome": "lost", "missing_stages": ["discovery"], "qa_score_hint": 42, "linked_root_cause": "RC-000077", "utterances": [{"turn": 1, "speaker": "agent", "text": "Em chào anh/chị, em Phúc bên Sửa chữa.", "stage": "opening", "emotion": "neutral", "intent": "ready_to_buy"}, {"turn": 2, "speaker": "customer", "text": "Em đang hơi bận, nói ngắn được không?", "stage": "rapport", "emotion": "exit_intent", "intent": "fake_agreement"}, {"turn": 3, "speaker": "agent", "text": "Anh/chị cần triển khai trong thời gian nào ạ?", "stage": "qualification", "emotion": "confused", "intent": "soft_rejection"}, {"turn": 4, "speaker": "customer", "text": "Phần nào giải quyết đúng tiết kiệm chi phí của em?", "stage": "presentation", "emotion": "interested", "intent": "price_concern"}, {"turn": 5, "speaker": "agent", "text": "Em tách chi phí và giá trị để dễ so ạ.", "stage": "pricing", "emotion": "curious", "intent": "need_more_time"}, {"turn": 6, "speaker": "customer", "text": "Đắt quá.", "stage": "objection", "emotion": "hesitation", "intent": "trust_issue"}, {"turn": 7, "speaker": "agent", "text": "Nếu phù hợp, mình chốt lịch giao hàng trong tuần này ạ?", "stage": "closing", "emotion": "frustration", "intent": "decision_maker_missing"}, {"turn": 8, "speaker": "customer", "text": "Tuần này em mới quyết được.", "stage": "follow_up", "emotion": "angry", "intent": "competitor_comparison"}, {"turn": 9, "speaker": "agent", "text": "Em gọi lại theo yêu cầu đăng ký của anh/chị ạ.", "stage": "opening", "emotion": "trust", "intent": "busy"}, {"turn": 10, "speaker": "customer", "text": "Nghe giọng thân thiện đấy.", "stage": "rapport", "emotion": "excited", "intent": "interested"}, {"turn": 11, "speaker": "agent", "text": "Ngân sách dự kiến của anh/chị khoảng bao nhiêu ạ?", "stage": "qualification", "emotion": "neutral", "in