INSERT INTO vecd_conversations(id, payload) VALUES ('CONV-000080', '{"id": "CONV-000080", "dialect": "central", "industry": "b2b_services", "kind": "friendly_customer", "turn_count": 19, "outcome": "won", "missing_stages": [], "qa_score_hint": 85, "linked_root_cause": "RC-000080", "utterances": [{"turn": 1, "speaker": "agent", "text": "Em xin phép 2 phút tư vấn Dịch vụ doanh nghiệp ạ.", "stage": "opening", "emotion": "interested", "intent": "price_concern"}, {"turn": 2, "speaker": "customer", "text": "Em muốn hiểu rõ đã rồi tính.", "stage": "rapport", "emotion": "curious", "intent": "need_more_time"}, {"turn": 3, "speaker": "agent", "text": "Tiêu chí mô quan trọng nhất?", "stage": "discovery", "emotion": "hesitation", "intent": "trust_issue"}, {"turn": 4, "speaker": "customer", "text": "Hợp thì em mới làm tiếp.", "stage": "qualification", "emotion": "frustration", "intent": "decision_maker_missing"}, {"turn": 5, "speaker": "agent", "text": "Dựa trên nhu cầu minh bạch hợp đồng, em đề xuất hướng này.", "stage": "presentation", "emotion": "angry", "intent": "competitor_comparison"}, {"turn": 6, "speaker": "customer", "text": "Gói này gồm chi?", "stage": "pricing", "emotion": "trust", "intent": "busy"}, {"turn": 7, "speaker": "agent", "text": "Em gửi giấy tờ/uy tín để anh/chị yên tâm.", "stage": "objection", "emotion": "excited", "intent": "interested"}, {"turn": 8, "speaker": "customer", "text": "Nếu ổn thì bước tiếp theo là chi?", "stage": "closing", "emotion": "neutral", "intent": "ready_to_buy"}, {"turn": 9, "speaker": "agent", "text": "Em gọi lại theo lịch, anh/chị tiện nghe không?", "stage": "follow_up", "emotion": "exit_intent", "intent": "fake_agreement"}, {"turn": 10, "speaker": "customer", "text": "Cho em hỏi thông tin Dịch vụ doanh nghiệp với.", "stage": "opening", "emotion": "confused", "intent": "soft_rejection"}, {"turn": 11, "speaker": "agent", "text": "Em hiểu anh/chị đang bận, em nói ngắn.", "stage": "rapport", "emotion": "interested", "intent": "price_concern"}, {"turn": 12, "speaker": "customer", "text": "Nhu cầu chính là triển khai nhanh.", "stage": "discovery", "emotion": "curious", "intent": "need_more_time"}, {"turn": 13, "speaker": "agent", "text": "Anh/chị cần làm trong thời gian mô?", "stage": "qualification", "emotion": "hesitation", "intent": "trust_issue"}, {"turn": 14, "speaker": "customer", "text": "Có case giống em không?", "stage": "presentation", "emotion": "frustration", "intent": "decision_maker_missing"}, {"turn": 15, "speaker": "agent", "text": "Chốt trong tuần ni có ưu đãi thêm.", "stage": "pricing", "emotion": "angry", "intent": "competitor_comparison"}, {"turn": 16, "speaker": "customer", "text": "Có lừa không?", "stage": "objection", "emotion": "trust", "intent": "busy"}, {"turn": 17, "speaker": "agent", "text": "Nếu phù hợp, mình chốt lịch khảo sát trong tuần ni?", "stage": "closing", "emotion": "excited", "intent": "interested"}, {"turn": 18, "speaker": "customer", "text": "Tuần ni em mới quyết được.", "stage": "follow_up", "emotion": "neutral", "intent": "ready_to_buy"}, {"turn": 19, "speaker": "agent", "text": "Em gọi lại theo đăng ký của anh/chị.", "stage": "opening", "emotion": "exit_intent", "intent": "fake_agreement"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET payload = EXCLUDED.payload;
